/* Lot 96: fractional angles and repeating gradients from the reader sheet to the engine's cells (generated by scripts/lot96_gradgen.py; expectations from scripts/lot96_gradmodel.py and lot94_gradmodel.py). */

#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"
#include "webeng.h"

static wf_site_t g_d;
static we_doc_t g_doc;
static char g_html[4096], g_attr[1400], g_out[2048];

/* the sheet through the reader; its style on a w x h div; the engine's
 * rectangles as in test_lot96_cells.c */
static const char *sheet(const char *css, int w, int h) {
    int i, n = 0;
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body><div id=t>t</div></body></html>", css);
    if (wf_site_prepare(&g_d, g_html, (int)strlen(g_html)) != 0) return "PREPARE FAILED";
    g_attr[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, "t")) wf_site_style_attr(&g_d, g_d.node[i].start, g_attr, (int)sizeof(g_attr));
    if (strncmp(g_attr, " style=\"", 8) != 0) return "NO STYLE";
    snprintf(g_html, sizeof(g_html), "<html><body style='margin:0'><div style=\"width:%dpx;height:%dpx;%s></div></body></html>",
             w, h, g_attr + 8);
    if (we_render(&g_doc, g_html, (int)strlen(g_html), 320) != 0) return "RENDER FAILED";
    for (i = 0; i < (int)g_doc.ndiag; i++) if (strstr(g_doc.diag[i], "refused")) return "REFUSED";
    g_out[0] = 0;
    for (i = 0; i < (int)g_doc.nitems; i++) {
        const os_fb_web_item_t *it = &g_doc.items[i];
        if (it->kind != OS_FB_WEB_RECT) continue;
        n += snprintf(g_out + n, sizeof(g_out) - (size_t)n, "%s%d %d %d %d %08X", n ? ";" : "", it->x, it->y,
                      (int)it->w, (int)it->h, (unsigned)it->color);
    }
    return g_out;
}

